test("09:00 to 11:00 and 10:30 to 12:00 overlap by 30 minutes", function () {
  var actual = code.windowOverlap({ start: "09:00", end: "11:00" }, { start: "10:30", end: "12:00" });
  assert.deepEqual(actual, { overlaps: true, minutes: 30 });
});

test("09:00 to 12:00 and 12:00 to 13:00 only touch and do not overlap", function () {
  var actual = code.windowOverlap({ start: "09:00", end: "12:00" }, { start: "12:00", end: "13:00" });
  assert.deepEqual(actual, { overlaps: false, minutes: 0 });
});

test("10:30 to 12:00 and 09:00 to 11:00 overlap by 30 minutes in swapped order", function () {
  var actual = code.windowOverlap({ start: "10:30", end: "12:00" }, { start: "09:00", end: "11:00" });
  assert.deepEqual(actual, { overlaps: true, minutes: 30 });
});

test("12:00 to 13:00 and 09:00 to 12:00 only touch and do not overlap in swapped order", function () {
  var actual = code.windowOverlap({ start: "12:00", end: "13:00" }, { start: "09:00", end: "12:00" });
  assert.deepEqual(actual, { overlaps: false, minutes: 0 });
});

test("08:00 to 09:00 and 10:00 to 11:00 are separate and do not overlap", function () {
  var actual = code.windowOverlap({ start: "08:00", end: "09:00" }, { start: "10:00", end: "11:00" });
  assert.deepEqual(actual, { overlaps: false, minutes: 0 });
});

test("10:00 to 11:00 and 08:00 to 09:00 are separate and do not overlap in swapped order", function () {
  var actual = code.windowOverlap({ start: "10:00", end: "11:00" }, { start: "08:00", end: "09:00" });
  assert.deepEqual(actual, { overlaps: false, minutes: 0 });
});

test("09:00 to 12:00 fully covers 10:00 to 11:00 and overlaps by 60 minutes", function () {
  var actual = code.windowOverlap({ start: "09:00", end: "12:00" }, { start: "10:00", end: "11:00" });
  assert.deepEqual(actual, { overlaps: true, minutes: 60 });
});

test("10:00 to 11:00 inside 09:00 to 12:00 overlaps by 60 minutes in swapped order", function () {
  var actual = code.windowOverlap({ start: "10:00", end: "11:00" }, { start: "09:00", end: "12:00" });
  assert.deepEqual(actual, { overlaps: true, minutes: 60 });
});
